    private static readonly Dictionary<string, Glyph> ByLabel =
        Table.ToDictionary(g => g.Label, StringComparer.Ordinal);


    private static readonly Dictionary<string, string> ExtensionToLabel = BuildExtensionMap();

    public static IReadOnlyList<Glyph> All => Table;

    public static Glyph? Find(string label) => ByLabel.TryGetValue(label, out var glyph) ? glyph : null;






    public static Glyph Detect(string? fileName, bool isFolder)
    {
        if (isFolder) return ByLabel[FolderLabel];

        var extension = Path.GetExtension(fileName ?? string.Empty);
        if (extension.Length < 2) return ByLabel[UnknownLabel];

        var key = extension[1..].ToLowerInvariant();
        return ExtensionToLabel.TryGetValue(key, out var label) && ByLabel.TryGetValue(label, out var glyph)
            ? glyph
            : ByLabel[UnknownLabel];
    }

    private static Dictionary<string, string> BuildExtensionMap()
    {
        var map = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var glyph in Table)
        {
            if (glyph.Label is FolderLabel or UnknownLabel) continue;
            map[glyph.Label.ToLowerInvariant()] = glyph.Label;
        }


        map["jpeg"] = "JPG";
        map["jpe"] = "JPG";
        map["tif"] = "TIFF";
        map["htm"] = "HTML";
        map["yml"] = "YAML";
        map["markdown"] = "MD";
        map["7zip"] = "7Z";
        return map;
    }
}
